/**
 * @description Tests for Connection Type Apex Auth (the Auth Class adds the login, a 401 logs in again and resends once,
 * a missing class fails for good, secrets are masked, Check connection runs the login), the callout budget of a send
 * job, and auto-retry (temporary failures get Next Retry At with backoff, permanent ones never do, the maximum stops it,
 * the sweep hands due transactions to the Sender, the schedule is idempotent). Records that lead to a callout are
 * changed after Test.startTest, as in IntegrationHubOutboundTest.
 */
@IsTest
private class IntegrationHubAuthRetryTest {

    private static final String STUB_AUTH = 'IntegrationHubTestData.StubAuth';

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    /* Datetime fields keep whole seconds. */
    private static Datetime wholeSeconds(Datetime value) {
        return Datetime.newInstance(value.getTime() / 1000 * 1000);
    }

    private static IntegrationHubCallout.Delivery delivery(IH_Connection__c conn) {
        IH_Event__c ev = new IH_Event__c(Active__c = true, Event_Key__c = 'BUDGET', Path__c = '/budget', Http_Method__c = 'POST');
        IntegrationHubCallout.Delivery d = new IntegrationHubCallout.Delivery(new IH_Transaction__c(), ev);
        d.conn = conn;
        d.body = '{}';
        return d;
    }

    private static Id sendOne(String key) {
        return IntegrationHub.publish(key, new List<SObject>{ IntegrationHubTestData.accounts()[0] })[0];
    }

    /* ------------------------------------------------------------------ Apex Auth */

    @IsTest
    static void authClassAddsTheHeader() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.AuthMock(IntegrationHubTestData.ACCEPT_ANY));
            Test.startTest();
            IntegrationHubTestData.useApexAuth(STUB_AUTH);
            Id txnId = sendOne(IntegrationHubTestData.OUT_KEY);
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.retryState(txnId);
            Assert.areEqual('Success', t.Status__c, 'the system accepted the login: ' + t.Error_Message__c);
            Assert.areEqual('Bearer OLD', t.External_Reference_Id__c, 'the Auth Class header was sent');
        }
    }

    @IsTest
    static void unauthorizedLogsInAgainAndResendsOnce() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.AuthMock(IntegrationHubTestData.REJECT_OLD));
            Test.startTest();
            IntegrationHubTestData.useApexAuth(STUB_AUTH);
            Id txnId = sendOne(IntegrationHubTestData.OUT_KEY);
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.retryState(txnId);
            Assert.areEqual('Success', t.Status__c, 'the resend with the new token succeeded: ' + t.Error_Message__c);
            Assert.areEqual('Bearer NEW', t.External_Reference_Id__c, 'the refreshed token was sent');
            Assert.areEqual(1, [SELECT COUNT() FROM IH_Attempt__c WHERE Transaction__c = :txnId WITH SYSTEM_MODE],
                'the login and the resend are one attempt');
        }
    }

    @IsTest
    static void missingAuthClassFailsForGood() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.AuthMock(IntegrationHubTestData.ACCEPT_ANY));
            Test.startTest();
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 3, 15);
            IntegrationHubTestData.useApexAuth('NoSuchAuthClassAnywhere');
            Id txnId = sendOne(IntegrationHubTestData.OUT_KEY);
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.retryState(txnId);
            Assert.areEqual('Failed', t.Status__c, 'a missing class fails the send');
            Assert.isTrue(t.Error_Message__c.contains('was not found'), 'the reason is in plain words: ' + t.Error_Message__c);
            Assert.isNull(t.Next_Retry_At__c, 'a missing class is permanent: never retried automatically');
        }
    }

    @IsTest
    static void tokenUrlDownIsTemporary() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.AuthMock(IntegrationHubTestData.ACCEPT_ANY));
            Test.startTest();
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 3, 15);
            IntegrationHubTestData.useApexAuth('IntegrationHubTestData.StubAuthOffline');
            Id txnId = sendOne(IntegrationHubTestData.OUT_KEY);
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.retryState(txnId);
            Assert.areEqual('Failed', t.Status__c, 'the login could not reach the token URL');
            Assert.isTrue(t.Error_Message__c.contains('Read timed out'), 'the reason is kept: ' + t.Error_Message__c);
            Assert.isNotNull(t.Next_Retry_At__c, 'a token URL that is down is temporary: auto-retry is planned');
            Assert.isTrue(IntegrationHubConnectionAuth.isCalloutProblem(
                new IntegrationHub.HubException('wrapped', new CalloutException('down'))), 'a wrapped callout error counts');
            Assert.isFalse(IntegrationHubConnectionAuth.isCalloutProblem(new IntegrationHub.HubException('no')), 'other errors do not');
        }
    }

    @IsTest
    static void authClassErrorsAreExplained() {
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Connection__c conn = new IH_Connection__c(Name = 'Partner', Connection_Type__c = 'Apex Auth');
            IntegrationHub.AuthContext ctx = new IntegrationHub.AuthContext();
            ctx.request = new HttpRequest();
            ctx.connection = conn;
            Assert.isTrue(IntegrationHubConnectionAuth.runAuthClass(ctx).contains('no Auth Class'), 'blank class');
            conn.Auth_Class__c = 'IntegrationHubTestData';
            Assert.isTrue(IntegrationHubConnectionAuth.runAuthClass(ctx).contains('does not implement'), 'wrong class');
            conn.Auth_Class__c = 'IntegrationHubTestData.StubAuthBroken';
            Assert.isTrue(IntegrationHubConnectionAuth.runAuthClass(ctx).contains('could not log in: login refused'),
                'the class error is kept');
            conn.Auth_Class__c = STUB_AUTH;
            ctx.refresh = true;
            Assert.isNull(IntegrationHubConnectionAuth.runAuthClass(ctx), 'a working class');
            Assert.areEqual('Bearer NEW', ctx.request.getHeader('Authorization'), 'the refresh flag reaches the class');
            Assert.isNull(IntegrationHubConnectionAuth.runAuthClass(new IntegrationHub.AuthContext()), 'no connection: nothing');
            conn.Connection_Type__c = null;
            Assert.isNull(IntegrationHubConnectionAuth.runAuthClass(ctx), 'blank type is Named Credential: no class runs');
            Assert.areEqual(1, IntegrationHubConnectionAuth.calloutsPerSend(conn), 'a Named Credential send is one callout');
        }
    }

    @IsTest
    static void secretsAreMasked() {
        System.runAs(IntegrationHubTestData.admin()) {
            Assert.areEqual('Bearer ' + IntegrationHubHeaderMask.MASK, IntegrationHubHeaderMask.maskValue('Authorization', 'Bearer abc.def'),
                'the scheme stays, the token is hidden');
            Assert.areEqual(IntegrationHubHeaderMask.MASK, IntegrationHubHeaderMask.maskValue('X-API-Key', 'k-123'), 'an API key');
            Assert.areEqual(IntegrationHubHeaderMask.MASK, IntegrationHubHeaderMask.maskValue('client_secret', 'abc def'),
                'a value with a space that is not a scheme');
            Assert.areEqual(IntegrationHubHeaderMask.MASK, IntegrationHubHeaderMask.maskValue('X-Auth-Token', 'abc'), 'a token');
            Assert.areEqual('2', IntegrationHubHeaderMask.maskValue('X-Api-Version', '2'), 'other headers are shown');
            Assert.areEqual('{!$Credential.Partner.key}', IntegrationHubHeaderMask.maskValue('apikey', '{!$Credential.Partner.key}'),
                'a merge field is not a secret');
            IH_Connection__c conn = new IH_Connection__c(Connection_Type__c = 'Apex Auth', Auth_Class__c = 'PartnerAuth',
                Headers__c = '{"X-Token":"abc","x-api-version":"2"}');
            Map<String, String> shown = new Map<String, String>();
            for (IntegrationHubPreview.Header h : IntegrationHubPreview.sendHeaders('corr', conn)) {
                shown.put(h.name, h.value);
            }
            Assert.areEqual('added by PartnerAuth at send time (hidden)', shown.get('Authorization'), 'the auth line is shown');
            Assert.areEqual(IntegrationHubHeaderMask.MASK, shown.get('X-Token'), 'a token header is masked');
            Assert.areEqual('2', shown.get('x-api-version'), 'a plain header is shown');
        }
    }

    @IsTest
    static void previewAndViewRequestHideTheLogin() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubTestData.useApexAuth(STUB_AUTH);
            IH_Event__c ev = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY);
            IntegrationHubPreview.Preview p = IntegrationHubPreview.previewPayload(ev.Id, IntegrationHubTestData.accounts()[0].Id);
            Boolean hidden = false;
            for (IntegrationHubPreview.Header h : p.headers) {
                hidden = hidden || (h.name == 'Authorization' && h.value.contains('at send time (hidden)'));
            }
            Assert.isTrue(hidden, 'Preview payload says the login is added at send time');
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubPreview.Exchange x = IntegrationHubPreview.getExchange(t.Id);
            Boolean inExchange = false;
            for (IntegrationHubPreview.Header h : x.requestHeaders) {
                inExchange = inExchange || (h.name == 'Authorization' && h.value.startsWith('added by ' + STUB_AUTH));
            }
            Assert.isTrue(inExchange, 'View request says the login is added at send time');
        }
    }

    @IsTest
    static void checkConnectionRunsTheLogin() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Connection__c good = new IH_Connection__c(Name = 'Auth good', Named_Credential__c = 'IH_Check', Active__c = true,
                Connection_Type__c = 'Apex Auth', Auth_Class__c = STUB_AUTH);
            IH_Connection__c broken = new IH_Connection__c(Name = 'Auth broken', Named_Credential__c = 'IH_Check', Active__c = true,
                Connection_Type__c = 'Apex Auth', Auth_Class__c = 'IntegrationHubTestData.StubAuthBroken');
            IntegrationHubData.insertAll(new List<IH_Connection__c>{ good, broken });
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.AuthMock(IntegrationHubTestData.ACCEPT_ANY));
            Test.startTest();
            IntegrationHubEndpointCheck.CheckResult ok = IntegrationHubEndpointCheck.checkConnection(good.Id);
            IntegrationHubEndpointCheck.CheckResult refused = IntegrationHubEndpointCheck.checkConnection(broken.Id);
            Test.stopTest();
            Assert.isTrue(ok.reached, 'the login header was added, so the system answered');
            Assert.areEqual(200, ok.statusCode, 'the system accepted it');
            Assert.isFalse(refused.reached, 'a failed login calls nothing');
            Assert.isTrue(refused.message.contains('login') && refused.message.contains('login refused'),
                'the login problem is in plain words: ' + refused.message);
            Assert.isTrue(IntegrationHubEndpointCheck.authMessage(401, good, 'other').contains('Auth Class ' + STUB_AUTH),
                'a 401 points at the Auth Class');
            Assert.areEqual('other', IntegrationHubEndpointCheck.authMessage(200, good, 'other'), 'other answers as before');
        }
    }

    /* ------------------------------------------------------------------ callout budget */

    @IsTest
    static void calloutBudgetKeepsRoomForTheLogin() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubCallout.Delivery named = new IntegrationHubCallout.Delivery(new IH_Transaction__c(), new IH_Event__c());
            named.conn = new IH_Connection__c(Timeout_Seconds__c = 10);
            IntegrationHubCallout.Delivery apexAuth = new IntegrationHubCallout.Delivery(new IH_Transaction__c(), new IH_Event__c());
            apexAuth.conn = new IH_Connection__c(Timeout_Seconds__c = 10, Connection_Type__c = 'Apex Auth', Auth_Class__c = STUB_AUTH);
            Assert.isTrue(IntegrationHubConnectionAuth.fitsInJob(named, 0L, 4), 'one callout plus the margin fits in 4');
            Assert.isFalse(IntegrationHubConnectionAuth.fitsInJob(apexAuth, 0L, 4), 'an Apex Auth send needs room for 4 callouts');
            Assert.isTrue(IntegrationHubConnectionAuth.fitsInJob(apexAuth, 0L, null), 'it fits within the real limit of 100');
            Assert.isFalse(IntegrationHubConnectionAuth.fitsInJob(named, 105000L, null), 'no time left: chained to the next job');
        }
    }

    @IsTest
    static void sendJobStopsBeforeTheCalloutLimit() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.AuthMock(IntegrationHubTestData.ACCEPT_ANY));
            IH_Connection__c named = new IH_Connection__c(Name = 'Named', Active__c = true, Named_Credential__c = 'IH_Test');
            IH_Connection__c apexAuth = new IH_Connection__c(Name = 'Apex', Active__c = true, Named_Credential__c = 'IH_Test',
                Connection_Type__c = 'Apex Auth', Auth_Class__c = STUB_AUTH);
            Test.startTest();
            IntegrationHubSender.calloutLimit = 3;
            List<IntegrationHubCallout.Delivery> small = new List<IntegrationHubCallout.Delivery>{
                delivery(named), delivery(named), delivery(apexAuth) };
            List<Id> rest = IntegrationHubSender.send(small);
            Integer afterSmall = Limits.getCallouts();
            IntegrationHubSender.calloutLimit = null;
            List<Id> none = IntegrationHubSender.send(new List<IntegrationHubCallout.Delivery>{ delivery(apexAuth) });
            Test.stopTest();
            Assert.areEqual(1, afterSmall, 'only one send fits under a limit of 3 with the margin');
            Assert.areEqual(2, rest.size(), 'the others are left for the next job');
            Assert.isTrue(small[0].attempted && !small[1].attempted && !small[2].attempted, 'the first one was sent');
            Assert.isTrue(none.isEmpty(), 'an Apex Auth send fits within the real limit');
            Assert.isTrue(Limits.getCallouts() <= Limits.getLimitCallouts(), 'never past the limit');
        }
    }

    /* ------------------------------------------------------------------ auto-retry planning */

    @IsTest
    static void temporaryFailureIsPlannedWithBackoff() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(503, 'down'));
            Datetime before = System.now();
            Test.startTest();
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 3, 15);
            Id txnId = sendOne(IntegrationHubTestData.OUT_KEY);
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.retryState(txnId);
            Assert.areEqual('Failed', t.Status__c, 'a temporary failure stays Failed');
            Assert.isNotNull(t.Next_Retry_At__c, 'the next try is planned');
            Assert.isTrue(t.Next_Retry_At__c >= before.addMinutes(15).addSeconds(-1), 'after Retry After minutes');
            Assert.isTrue(t.Next_Retry_At__c <= System.now().addMinutes(15).addSeconds(1), 'not later than that');
            Assert.isTrue(t.Error_Message__c.contains('Will retry automatically at') && t.Error_Message__c.contains('(1 of 3)'),
                'the message says when: ' + t.Error_Message__c);
            Assert.isTrue(t.Error_Summary__c.endsWith('(temporary: will retry automatically)'), 'the summary has no time');
            Assert.areEqual(3, t.Auto_Retry_Max__c, 'the event maximum is shown on the transaction');
        }
    }

    @IsTest
    static void backoffDoublesAndStops() {
        System.runAs(IntegrationHubTestData.admin()) {
            Datetime now = System.now();
            IH_Event__c ev = new IH_Event__c(Auto_Retry_Max__c = 3, Retry_After_Minutes__c = 15);
            Assert.areEqual(now.addMinutes(15), IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(), ev, now), 'first: 15');
            Assert.areEqual(now.addMinutes(30), IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(Auto_Retries__c = 1), ev, now),
                'second: 30');
            Assert.areEqual(now.addMinutes(60), IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(Auto_Retries__c = 2), ev, now),
                'third: 60');
            Assert.isNull(IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(Auto_Retries__c = 3), ev, now), 'max reached');
            Assert.areEqual(now.addMinutes(15), IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(),
                new IH_Event__c(Auto_Retry_Max__c = 1), now), 'blank Retry After is 15');
            Assert.areEqual(now.addMinutes(10080), IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(Auto_Retries__c = 9),
                new IH_Event__c(Auto_Retry_Max__c = 10, Retry_After_Minutes__c = 1440), now), 'at most one week');
            Assert.isNull(IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(), new IH_Event__c(), now), 'off when blank');
            Assert.isNull(IntegrationHubRetryPlan.nextRetryAt(new IH_Transaction__c(), null, now), 'off without an event');
        }
    }

    @IsTest
    static void permanentFailureIsNeverRetried() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(422, 'bad data'));
            Test.startTest();
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 3, 15);
            Id txnId = sendOne(IntegrationHubTestData.OUT_KEY);
            Test.stopTest();
            IH_Transaction__c t = IntegrationHubTestData.retryState(txnId);
            Assert.areEqual('Failed', t.Status__c, '422 fails');
            Assert.isNull(t.Next_Retry_At__c, 'a permanent rejection is never retried automatically');
            Assert.isFalse(t.Error_Message__c.contains('Will retry'), 'and the message does not promise it');
