    @IsTest
    static void maximumReachedStopsRetrying() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(503, 'still down'));
            Test.startTest();
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 3, 15);
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{ new IH_Transaction__c(Id = t.Id, Auto_Retries__c = 2) });
            // As the sweep does: Retry and Auto Retries 2 -> 3.
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{
                new IH_Transaction__c(Id = t.Id, Status__c = 'Retry', Auto_Retries__c = 3, Next_Retry_At__c = null) });
            Test.stopTest();
            IH_Transaction__c after = IntegrationHubTestData.retryState(t.Id);
            Assert.areEqual('Failed', after.Status__c, 'the third automatic retry failed too');
            Assert.isNull(after.Next_Retry_At__c, 'no fourth try');
            Assert.isTrue(after.Error_Message__c.contains('auto-retry stopped after 3 of 3'), 'the message says so: ' + after.Error_Message__c);
            IH_Attempt__c attempt = [SELECT Kind__c FROM IH_Attempt__c WHERE Transaction__c = :t.Id WITH SYSTEM_MODE LIMIT 1];
            Assert.areEqual(IntegrationHubSender.KIND_AUTO_RETRY, attempt.Kind__c, 'a send by the sweep is logged as Auto Retry');
        }
    }

    @IsTest
    static void deadSendJobIsPlannedForRetry() {
        System.runAs(IntegrationHubTestData.admin()) {
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 2, 30);
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Pending');
            new IntegrationHubSender.Recovery(new List<Id>{ t.Id })
                .execute(new IntegrationHubTestData.StubFinalizerContext(ParentJobResult.UNHANDLED_EXCEPTION));
            IH_Transaction__c after = IntegrationHubTestData.retryState(t.Id);
            Assert.areEqual('Failed', after.Status__c, 'the dead job marks it Failed');
            Assert.isNotNull(after.Next_Retry_At__c, 'a stopped job is temporary: auto-retry is planned');
        }
    }

    /* ------------------------------------------------------------------ sweep, manual retry, schedule */

    @IsTest
    static void sweepHandsDueTransactionsToTheSender() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{}'));
            Test.startTest();
            IntegrationHubTestData.setAutoRetry(IntegrationHubTestData.OUT_KEY, 3, 15);
            IH_Transaction__c due = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IH_Transaction__c later = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{
                new IH_Transaction__c(Id = due.Id, Next_Retry_At__c = System.now().addMinutes(-1), Auto_Retries__c = 1),
                new IH_Transaction__c(Id = later.Id, Next_Retry_At__c = System.now().addHours(1)) });
            Assert.areEqual(1, IntegrationHubAutoRetry.dueCount(), 'one transaction is due');
            List<IH_Transaction__c> rows = IntegrationHubAutoRetry.retryRows(new List<SObject>{ new IH_Transaction__c(Id = due.Id,
                Auto_Retries__c = 1) });
            Assert.areEqual(1, rows.size(), 'one row per due transaction');
            Assert.areEqual(2, rows[0].Auto_Retries__c, 'Auto Retries goes up');
            Database.executeBatch(new IntegrationHubAutoRetry(), IntegrationHubAutoRetry.CHUNK);
            Test.stopTest();
            IH_Transaction__c sent = IntegrationHubTestData.retryState(due.Id);
            Assert.isTrue(sent.Status__c == 'Retry' || sent.Status__c == 'Success', 'the due one was handed on: ' + sent.Status__c);
            Assert.areEqual(2, sent.Auto_Retries__c, 'Auto Retries counts it');
            Assert.isNull(sent.Next_Retry_At__c, 'Next Retry At is cleared');
            IH_Transaction__c waiting = IntegrationHubTestData.retryState(later.Id);
            Assert.areEqual('Failed', waiting.Status__c, 'a transaction not yet due waits');
            Assert.isNotNull(waiting.Next_Retry_At__c, 'and keeps its time');
        }
    }

