    @IsTest
    static void manualRetryClearsThePlan() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{
                new IH_Transaction__c(Id = t.Id, Next_Retry_At__c = System.now().addMinutes(10), Auto_Retries__c = 1) });
            Assert.areEqual(1, IntegrationHubMonitorController.retryIds(new List<Id>{ t.Id }), 'retried by hand');
            IH_Transaction__c after = IntegrationHubTestData.retryState(t.Id);
            Assert.areEqual('Retry', after.Status__c, 'waits for the send');
            Assert.isNull(after.Next_Retry_At__c, 'a manual retry clears the planned one');
            Assert.isTrue(IntegrationHubRetryPlan.raisedIds(new List<IH_Transaction__c>{ after },
                new Map<Id, IH_Transaction__c>{ t.Id => new IH_Transaction__c(Id = t.Id, Auto_Retries__c = 1) }).isEmpty(),
                'a manual retry is not an automatic one');
        }
    }

