    @IsTest
    static void tokenCacheKeepsAndForgets() {
        System.runAs(IntegrationHubTestData.admin()) {
            Id connId = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Connection__c;
            Assert.isNull(IntegrationHubTokenCache.cachedToken(null), 'no connection, no token');
            IntegrationHubTokenCache.putToken(null, 'ignored', 600);
            IntegrationHubTokenCache.putToken(connId, 'T-1', 600);
            Assert.areEqual('T-1', IntegrationHubTokenCache.cachedToken(connId), 'kept for the job');
            IntegrationHubTokenCache.removeToken(connId);
            Assert.isNull(IntegrationHubTokenCache.cachedToken(connId), 'forgotten');
            IntegrationHubTokenCache.putToken(connId, 'T-2', 60);
            Assert.areEqual('T-2', IntegrationHubTokenCache.cachedToken(connId), 'a short life is kept in memory');
            IntegrationHubTokenCache.putToken(connId, 'T-3', 0);
            Assert.isNull(IntegrationHubTokenCache.cachedToken(connId), 'no life removes it');
            Assert.areEqual('ihtoken' + connId, IntegrationHubTokenCache.keyOf(connId), 'letters and digits only');
            IntegrationHubTokenCache.usePlatformCache = false;
            IntegrationHubTokenCache.putToken(connId, 'T-4', 900);
            Assert.areEqual('T-4', IntegrationHubTokenCache.cachedToken(connId), 'works without Platform Cache');
        }
    }

